// Cross-validation of the TypeScript analysis engine against the authoritative Python solver.
// fixtures.json is generated by `python web/scripts/make_fixtures.py` from clue/tools/{solver,analyst}.py.
import { describe, expect, it } from "vitest";
import fixtures from "./fixtures.json";
import { analyze, AnalysisSession, buildNotebook, defaultHandSizesFor } from "../analyst";
import { solve } from "../solver";

interface Fixture {
  session: AnalysisSession;
  expected: {
    hand_sizes: Record<string, number>;
    ok: boolean;
    consistent: boolean;
    exact: boolean;
    n_possible: number;
    combos: Record<string, number>;
    card_probs: Record<string, number>;
    holder_probs: Record<string, Record<string, number>>;
    certain_holder: Record<string, string>;
    deductions: string[];
    best: string[] | null;
    best_prob: number;
    accuse: boolean;
    suggestions: { room: string; score: number }[];
    threat: { opponents: Record<string, { n_possible: number; p_win_next_turn: number }>; max_threat: number; most_dangerous: string | null } | null;
    advice_first: string | null;
  };
}

const TOL = 1e-4;
const all = fixtures as unknown as Record<string, Fixture>;

describe.each(Object.keys(all))("fixture %s", (name) => {
  const { session, expected } = all[name];

  it("reproduces the Python solver exactly", () => {
    const sizes = defaultHandSizesFor(session);
    expect(sizes).toEqual(expected.hand_sizes);
    const { nb } = buildNotebook(session);
    const sol = solve(nb, session.players, sizes, session.edition);
    expect(sol.exact).toBe(expected.exact);
    expect(sol.nPossible).toBe(expected.n_possible);
    const combos: Record<string, number> = {};
    for (const c of sol.combos) combos[`${c.suspect} | ${c.weapon} | ${c.room}`] = c.p;
    expect(Object.keys(combos).sort()).toEqual(Object.keys(expected.combos).sort());
    for (const [k, p] of Object.entries(expected.combos)) expect(combos[k], `combo ${k}`).toBeCloseTo(p, 3);
    for (const [card, p] of Object.entries(expected.card_probs)) expect(sol.cardProbs[card] ?? 0, `card ${card}`).toBeCloseTo(p, 3);
    for (const [card, probs] of Object.entries(expected.holder_probs)) {
      const got = sol.holderProbs[card] ?? {};
      expect(Object.keys(got).sort(), `holders of ${card}`).toEqual(Object.keys(probs).sort());
      for (const [h, p] of Object.entries(probs)) expect(Math.abs((got[h] ?? 0) - p), `P(${card} @ ${h})`).toBeLessThan(TOL);
    }
    expect(sol.certainHolder).toEqual(expected.certain_holder);
  });

  it("reproduces the Python analyst report", () => {
    const report = analyze(session);
    expect(report.ok).toBe(expected.ok);
    expect(report.consistent).toBe(expected.consistent);
    if (!expected.consistent) return; // conflict sessions short-circuit before the solver
    expect(report.deductions).toEqual(expected.deductions);
    expect(report.solution.best).toEqual(expected.best);
    expect(report.solution.best_prob).toBeCloseTo(expected.best_prob, 3);
    expect(report.guide.accusal.accuse).toBe(expected.accuse);
    expect(report.guide.suggestions.map((s) => ({ room: s.room, score: s.score }))).toEqual(expected.suggestions);
    if (expected.threat) {
      expect(report.threat.most_dangerous).toBe(expected.threat.most_dangerous);
      expect(report.threat.max_threat).toBeCloseTo(expected.threat.max_threat, 3);
      for (const [opp, d] of Object.entries(expected.threat.opponents)) {
        expect(report.threat.opponents[opp].n_possible, `threat ${opp}`).toBe(d.n_possible);
        expect(report.threat.opponents[opp].p_win_next_turn).toBeCloseTo(d.p_win_next_turn, 3);
      }
    }
    if (expected.advice_first) expect(report.guide.advice[0]).toBe(expected.advice_first);
  });
});

describe("large edition (sampled path)", () => {
  const session: AnalysisSession = {
    edition: "large",
    players: ["P1", "P2", "P3", "P4", "P5", "P6", "P7", "P8"],
    me: "P1",
    my_cards: ["Miss Scarlet", "Poison", "Attic", "Wadsworth"],
    faceup: ["Axe"],
    hand_sizes: null,
    observations: [
      { type: "suggestion", suggester: "P2", suspect: "Yvette", weapon: "Poker", room: "Gazebo", disprover: "P5" },
      { type: "suggestion", suggester: "P1", suspect: "Mr. Boddy", weapon: "Rope", room: "Cellar", disprover: "P3", shown_card: "Rope" },
      { type: "fact", player: "P4", card: "Garage", has: true },
    ],
  };

  it("returns sound, normalised sampled estimates", () => {
    const report = analyze(session);
    expect(report.ok).toBe(true);
    expect(report.consistent).toBe(true);
    expect(report.solution.exact).toBe(false);
    expect(report.solution.n_possible).toBeGreaterThan(1);
    // my own cards can never be in the envelope and are certainly mine
    for (const c of session.my_cards) {
      expect(report.holders[c]).toEqual({ P1: 1 });
      expect(report.solution.cards[c] ?? 0).toBe(0);
    }
    expect(report.holders["Rope"]).toEqual({ P3: 1 });
    expect(report.holders["Axe"]).toEqual({ faceup: 1 });
    // category marginals normalise to ~1 over the candidate envelopes
    let sum = 0;
    for (const combo of report.solution.combos) sum += combo.p;
    expect(sum).toBeLessThanOrEqual(1.0001);
    // deterministic: a second run returns identical estimates
    const again = analyze(session);
    expect(again.solution.combos).toEqual(report.solution.combos);
    expect(again.holders).toEqual(report.holders);
  });

  it("flags contradictions on big tables too", () => {
    const bad: AnalysisSession = { ...session, observations: [...session.observations, { type: "fact", player: "P2", card: "Poison", has: true }] };
    const report = analyze(bad);
    expect(report.ok).toBe(true);
    expect(report.consistent).toBe(false);
    expect(report.guide.advice[0]).toContain("contradictory");
  });
});
